    def gpu(self):
        # Only these two read-only device metadata commands are possible. They
        # inherit the observer's GNU-timeout group and have individual2s bounds.
        import subprocess
        def query(field):
            self.check();r=subprocess.run(['nvidia-smi',field,'--format=csv,noheader,nounits'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=min(2,max(.001,11-(time.monotonic()-self.start))),check=True)
            self.check();need(len(r.stdout)<=65536 and len(r.stderr)<=65536,'GPU metadata output cap');return r.stdout.decode()
        raw=query('--query-gpu=index,uuid');mapping={int(a.strip()):b.strip() for a,b in (line.split(',') for line in raw.splitlines() if line.strip())}
        need(mapping==dict(enumerate(self.cfg['gpu_uuids'])),'original GPU UUID map differs')
