def observe(c,rt):
    need(type(c) is dict and c.get('role') in CONTRACTS and exact(c,CONTRACTS[c['role']]),'exact original Sand observer contract required')
    role=c['role'];cfg=c['evaluation'];Q=cfg['queue_root'];started=rt.clocks();host=rt.host();boot=rt.boot()
    result={'schema':'sand_original_native_closure_metadata_observation_v1','role':role,'original_session':cfg['session_id'],'host':host,'boot_id':boot,'started':started,'scientific_admission':False,'new_analysis_clock_or_release':False,'remote_execution_success_established':False,'original_tool_exit_observed':False,'original_tool_exit_code':None,'original_remote_evaluator_exit_code':None,'native_closure_observed':False,'evaluation_closure_or_analysis_admission':False,'scientific_file_contents_read':False}
    if host!=cfg['hostname'] or boot!=cfg['boot_id']:
        result.update(status='wrong_original_host_or_boot',finished=rt.clocks());return result
    paths=[cfg['release_path']]+[Q+'/'+n for n in ('release_snapshot.json','queue_status.json','coverage_ledger.json','process_outcomes.json','gpu_observations.json')]
    metadata={};documents={};issues=[];verified=None
    for path in paths:
        try:
            raw=rt.read_raw(path,MAX_JSON);documents[path]=strict(raw);metadata[path]={'sha256':sha(raw),'bytes':len(raw),'status':'read'}
        except FileNotFoundError:metadata[path]={'status':'missing'}
        except Exception as exc:metadata[path]={'status':'cannot_observe','error':type(exc).__name__+': '+str(exc)};issues.append(path)
    try:
        need(metadata[cfg['release_path']]['sha256']==cfg['release_sha256'],'exact original release bytes required')
        pins={p:m['sha256'] for p,m in metadata.items() if m['status']=='read'}
        verified=validate_evaluation_closure(role,documents[cfg['release_path']],documents[Q+'/release_snapshot.json'],documents[Q+'/queue_status.json'],documents[Q+'/coverage_ledger.json'],documents[Q+'/process_outcomes.json'],documents.get(Q+'/gpu_observations.json'),pins)
    except Exception as exc:issues.append('historical_registry: '+type(exc).__name__+': '+str(exc))
    first={};second={};availability_first={};availability_final={};gpu_first=None;gpu_final=None
    if verified is not None:
        pids=sorted(set(cfg['historical_pids'])|{cfg['owner']['pid']}|{int(pid) for pid in verified['registered_children']});rt.allowed_pids.update(pids)
        release=documents[cfg['release_path']];stage_paths=[command[command.index('--output-dir')+1] for stream in release['streams'] for command in stream['commands']]
        need(len(stage_paths)==len(set(stage_paths))==(16 if role=='A' else 8),'full exact released stage directories required');rt.stage_paths.update(stage_paths)
        for pid in pids:
            try:first[str(pid)]=rt.native(pid)
            except Exception as exc:first[str(pid)]={'status':'cannot_observe','error_type':type(exc).__name__}
        for path in stage_paths:
            try:availability_first[path]=rt.availability(path)
            except Exception as exc:availability_first[path]={'state':'cannot_observe','error_type':type(exc).__name__}
        try:gpu_first=rt.gpu()
        except Exception as exc:issues.append('gpu_first: '+type(exc).__name__)
        for path in stage_paths:
            try:availability_final[path]=rt.availability(path)
            except Exception as exc:availability_final[path]={'state':'cannot_observe','error_type':type(exc).__name__}
    stable=True
    for path,meta in metadata.items():
        try:
            raw=rt.read_raw(path,MAX_JSON)
            if meta['status']!='read' or sha(raw)!=meta['sha256']:stable=False
        except FileNotFoundError:
            if meta['status']!='missing':stable=False
        except Exception:stable=False
    final_boot=rt.boot();rt.check()
    if verified is not None:
        for pid in pids:
            try:second[str(pid)]=rt.native(pid)
            except Exception as exc:second[str(pid)]={'status':'cannot_observe','error_type':type(exc).__name__}
        try:gpu_final=rt.gpu()
        except Exception as exc:issues.append('gpu_final: '+type(exc).__name__)
    native=verified is not None and not issues and stable and final_boot==boot and first and set(first)==set(second) and all(first[p]['status']==second[p]['status']=='absent' for p in first) and gpu_first is not None and gpu_final is not None and gpu_first['assigned_devices_empty'] is True and gpu_final['assigned_devices_empty'] is True
    def availability_pin(value):return sha(json.dumps(value,sort_keys=True,allow_nan=False).encode())
    final_availability={path:{'state':value['state'],'entries_count':len(value.get('entries',[])),'filename_stat_sha256':availability_pin(value),'error_type':value.get('error_type'),'scientific_file_contents_read':False} for path,value in availability_final.items()}
    result.update(status='observed_complete_original_native_closure_transport_exit_unresolved' if native else 'original_native_closure_not_established',native_closure_observed=bool(native),metadata=metadata,metadata_bytes_unchanged=stable,registry_issues=issues,complete_registered_child_ledger_checked=verified is not None,native_first=first,native_second=second,gpu_first=gpu_first,gpu_final=gpu_final,availability_first=availability_first,availability_first_sha256={path:availability_pin(value) for path,value in availability_first.items()},availability_final=final_availability,stage_filename_metadata_unchanged=exact(availability_first,availability_final),availability_is_not_numeric_completeness=True,final_boot_id=final_boot,finished=rt.clocks())
    if verified is not None:
        result.update(registered_children=verified['registered_children'],all_children_reaped=verified['all_children_reaped'],original_stage_outcomes=[{key:row[key] for key in ('stream','stage','outcome')} for row in verified['original_stage_outcomes']],original_queue_status=verified['original_queue_status'],original_abort_reason=verified['original_abort_reason'])
    return result

def main():
    need(sys.argv[1:2]==['--observe'] and len(sys.argv)==4 and sys.argv[2]=='--contract-sha256','explicit observer and contract pin required')
    need(sys.platform.startswith('linux') and sys.flags.isolated and sys.flags.no_site and sys.flags.dont_write_bytecode and not sys.flags.optimize,'isolated nonoptimized Linux required')
    raw=sys.stdin.buffer.read(32769);need(len(raw)<=32768 and sha(raw)==sys.argv[3],'bounded exact contract required');c=strict(raw)
    need(c.get('role') in CONTRACTS and exact(c,CONTRACTS[c['role']]),'exact role contract required')
    rt=Runtime(c);result=observe(c,rt);rt.check();encoded=json.dumps(result,sort_keys=True,allow_nan=False).encode();need(len(encoded)<=1024*1024,'metadata report cap');rt.check();sys.stdout.buffer.write(encoded+b'\n');sys.stdout.buffer.flush()
if __name__=='__main__':main()
